def max_of_list(lst):
    result = lst[0]
    for x in lst[1:]:
        if x > result:
            result = x
    return result

def fibonacci(n):
    a, b = 0, 1
    for _ in range(n):
        a, b = b, a + b
    return a

def is_palindrome(s):
    s = s.lower()
    return s == s[::-1]

def flatten(lst):
    result = []
    for sub in lst:
        result.extend(sub)
    return result
